INSERT INTO `Festival` (endDate, price, startDate, createdAt, id, updatedAt, city, street, title, url, description)
VALUES ('2025-10-10', 5000, '2025-10-01', '2025-08-29 07:29:23', 1, '2025-08-29 07:29:23', '전남 순천시', '순천만길',
        '순천만 갈대 축제', 'https://www.kebhana.com/', '순천만의 드넓은 갈대밭을 배경으로 음악회, 체험행사, 사진 콘테스트 등이 열려 가을 정취를 만끽할 수 있다.'),
       ('2026-05-07', 8000, '2026-05-02', '2025-08-29 07:29:23', 2, '2025-08-29 07:29:23', '전남 담양군', '죽녹원로',
